#include <omp.h>
#include <vector>
#include <algorithm>
#include <stdexcept>
#include <cstddef>

double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("sumOfMinimumElements: x and y must have the same size");
    }

    double sum = 0.0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for reduction(+:sum) schedule(static)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        sum += std::min(x[static_cast<std::size_t>(i)], y[static_cast<std::size_t>(i)]);
    }

    return sum;
}
